// ================= SETTINGS (fill these in) =================
const N8N_API_KEY = '***REDACTED***';
const GITHUB_TOKEN = '***REDACTED***';
const GITHUB_REPO = 'abdulrahman7a1/n8n-backups';
const BRANCH = 'main';
// Secrets written inside your OTHER workflows (e.g. your Steam API key).
// They get replaced with ***REDACTED*** before anything is uploaded.
const EXTRA_SECRETS = ['***REDACTED***'];
// =============================================================

const SECRETS = [N8N_API_KEY, GITHUB_TOKEN, ...EXTRA_SECRETS]
  .filter(s => s && !s.startsWith('PASTE_'));
const hide = (text) => {
  for (const s of SECRETS) text = text.split(s).join('***REDACTED***');
  return text;
};

const http = (opts) => this.helpers.httpRequest({ json: true, ...opts });

// 1) Get every workflow from n8n's own API
const workflows = [];
let cursor;
do {
  const res = await http({
    method: 'GET',
    url: 'http://localhost:5678/api/v1/workflows',
    headers: { 'X-N8N-API-KEY': N8N_API_KEY },
    qs: cursor ? { limit: 100, cursor } : { limit: 100 },
  });
  workflows.push(...(res.data ?? []));
  cursor = res.nextCursor;
} while (cursor);

// 2) Turn each workflow into a file: workflows/<name>-<id>.json
const files = workflows.map(wf => {
  const safe = (wf.name || 'workflow')
    .replace(/[^a-zA-Z0-9_-]+/g, '-').replace(/^-+|-+$/g, '') || 'workflow';
  const data = {
    id: wf.id, name: wf.name, active: wf.active, nodes: wf.nodes,
    connections: wf.connections, settings: wf.settings, updatedAt: wf.updatedAt,
  };
  return { path: `workflows/${safe}-${wf.id}.json`, content: hide(JSON.stringify(data, null, 2)) + '\n' };
});

// 3) Commit all files to GitHub as ONE commit
const gh = (method, path, body) => http({
  method,
  url: `https://api.github.com/repos/${GITHUB_REPO}${path}`,
  headers: {
    Authorization: `Bearer ${GITHUB_TOKEN}`,
    Accept: 'application/vnd.github+json',
    'User-Agent': 'n8n-backup',
    'X-GitHub-Api-Version': '2022-11-28',
  },
  ...(body ? { body } : {}),
});

const ref = await gh('GET', `/git/ref/heads/${BRANCH}`);
const parentSha = ref.object.sha;
const parent = await gh('GET', `/git/commits/${parentSha}`);

const tree = await gh('POST', '/git/trees', {
  base_tree: parent.tree.sha,
  tree: files.map(f => ({ path: f.path, mode: '100644', type: 'blob', content: f.content })),
});

// Nothing changed since the last backup -> no new commit
if (tree.sha === parent.tree.sha) {
  return [{ json: { status: 'No changes since last backup', workflows: workflows.length } }];
}

const when = new Date().toLocaleString('en-GB', { timeZone: 'Asia/Amman' });
const commit = await gh('POST', '/git/commits', {
  message: `Backup ${when} (${workflows.length} workflows)`,
  tree: tree.sha,
  parents: [parentSha],
});
await gh('PATCH', `/git/refs/heads/${BRANCH}`, { sha: commit.sha });

return [{ json: { status: 'Backed up', workflows: workflows.length, commit: commit.html_url } }];
